// The dist bundle [TH106, M1].
//
// One stylesheet and one module beside the loose files, for the consumer
// who wants two tags rather than eight. The loose files stay: vendoring
// a single stylesheet is what Almanac and kyu already do, and the bundle
// is an addition, not a replacement.
//
// Both halves are generated, and `--check` fails when either drifts from
// its sources -- the same promise every other generated file here makes.
//
// The stylesheet is a concatenation, in load order. That order is not
// cosmetic: css/themes.css opens with the @layer statement that
// establishes kp.base < kp.components < kp.register < kp.layout <
// kp.utilities, and the files that follow fill those layers. Reordering
// them would change which rule wins.
//
// The module is esbuild's bundle of js/auto.js, which is the one entry
// with a side effect. esbuild is already a dev dependency; nothing is
// added to what a consumer installs, and the bundle has no runtime
// dependency either (T6).
//
// Usage:
//   node gates/generate-bundle.mjs           write dist/
//   node gates/generate-bundle.mjs --check   exit 1 if either would change

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { join } from 'node:path';
import process from 'node:process';
import * as esbuild from 'esbuild';

const ROOT = fileURLToPath(new URL('../', import.meta.url));
const OUT = join(ROOT, 'dist');

/** In load order. See the header: this order decides which rule wins. */
export const STYLESHEETS = [
    'css/themes.css',
    'css/components.css',
    'css/cyberpunk-register.css',
    'css/retro-register.css',
    'css/layout.css',
    'css/utilities.css',
];

const version = JSON.parse(readFileSync(join(ROOT, 'package.json'), 'utf8')).version;

function css() {
    const head = `/* @kp-soft/themes v${version} — dist/kp-themes.css
   Generated by gates/generate-bundle.mjs — do not edit by hand.

   ${STYLESHEETS.join(', ')}, concatenated in load order. */\n\n`;
    return head + STYLESHEETS.map((file) => readFileSync(join(ROOT, file), 'utf8').trimEnd()).join('\n\n') + '\n';
}

async function js() {
    const result = await esbuild.build({
        entryPoints: [join(ROOT, 'js/auto.js')],
        bundle: true,
        format: 'esm',
        target: 'es2022',
        write: false,
        banner: {
            js: `/* @kp-soft/themes v${version} — dist/kp-themes.js\n   Generated by gates/generate-bundle.mjs — do not edit by hand.\n   js/auto.js and everything it imports, in one module. */`,
        },
    });
    return result.outputFiles[0].text;
}

const files = [
    { name: 'kp-themes.css', content: css() },
    { name: 'kp-themes.js', content: await js() },
];

if (process.argv.includes('--check')) {
    let stale = 0;
    for (const file of files) {
        const path = join(OUT, file.name);
        const current = existsSync(path) ? readFileSync(path, 'utf8') : '';
        if (current !== file.content) {
            stale++;
            console.error(`dist/${file.name} does not match its sources.`);
        }
    }
    if (stale > 0) {
        console.error('Run `npm run generate:bundle` and commit the result.');
        process.exit(1);
    }
    console.log(`Bundle: dist/kp-themes.css (${STYLESHEETS.length} stylesheets) and dist/kp-themes.js match their sources.`);
    process.exit(0);
}

mkdirSync(OUT, { recursive: true });
for (const file of files) writeFileSync(join(OUT, file.name), file.content);
console.log(`Wrote dist/kp-themes.css and dist/kp-themes.js.`);
